<span class="line">    formData<span class="token punctuation">.</span><span class="token function">append</span><span class="token punctuation">(</span><span class="token string">&#39;category&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;image&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
